<?php
namespace App\Http\Controllers;
use App\Models\{Transaksi,Pelanggan,Produk,DetailTransaksi,Pembayaran}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class TransaksiController extends Controller { public function index(){return view('transaksis.index',['transaksis'=>Transaksi::with('pelanggan')->latest()->paginate(10)]);} public function create(){return view('transaksis.create',['pelanggans'=>Pelanggan::orderBy('nama')->get(),'produks'=>Produk::orderBy('nama_produk')->get()]);} public function store(Request $r){$d=$r->validate(['pelanggan_id'=>'required|exists:pelanggans,id','produk_id'=>'required|exists:produks,id','berat'=>'required|numeric|min:0.1','metode'=>'nullable|string']);$p=Produk::findOrFail($d['produk_id']);$total=$p->harga*$d['berat'];$t=DB::transaction(function()use($d,$total){$t=Transaksi::create(['pelanggan_id'=>$d['pelanggan_id'],'tanggal_masuk'=>now(),'total'=>$total,'status'=>'Menunggu']);DetailTransaksi::create(['transaksi_id'=>$t->id,'produk_id'=>$d['produk_id'],'berat_jumlah'=>$d['berat'],'subtotal'=>$total]); if(!empty($d['metode'])) Pembayaran::create(['transaksi_id'=>$t->id,'jumlah'=>$total,'metode'=>$d['metode'],'status'=>'Lunas','tanggal'=>now()]);return $t;});return redirect()->route('transaksi.show',$t)->with('success','Transaksi berhasil dibuat.');} public function show(Transaksi $transaksi){$transaksi->load('pelanggan','details.produk','pembayaran');return view('transaksis.show',compact('transaksi'));}}
